-- Criação da tabela USUARIO
CREATE TABLE USUARIO (
    -- Escolha: GENERATED BY DEFAULT. Motivo: Permite que scripts de seed e testes informem 
    -- IDs manuais fixos sem falhar o INSERT. O trade-off aceito é o risco de descompasso 
    -- da sequência caso IDs manuais maiores sejam inseridos, exigindo o uso de setval() 
    -- para evitar colisões futuras.
    id_usuario INTEGER GENERATED BY DEFAULT AS IDENTITY,
    nome VARCHAR(100) NOT NULL,
    email VARCHAR(150) NOT NULL,
    senha VARCHAR(200) NOT NULL,
    data_hora_cadastro TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_usuario PRIMARY KEY (id_usuario)
);

CREATE UNIQUE INDEX ak_usuario_email ON USUARIO (LOWER(email));

-- Criação da tabela GRUPO
CREATE TABLE GRUPO (
    id_grupo INTEGER GENERATED BY DEFAULT AS IDENTITY,
    nome VARCHAR(100) NOT NULL,
    codigo_convite VARCHAR(50) NOT NULL,
    data_hora_criacao TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_grupo PRIMARY KEY (id_grupo),
    CONSTRAINT ak_grupo_codigo_convite UNIQUE (codigo_convite)
);

-- Criação da tabela PARTICIPACAO
CREATE TABLE PARTICIPACAO (
    id_participacao INTEGER GENERATED BY DEFAULT AS IDENTITY,
    id_usuario INTEGER NOT NULL,
    id_grupo INTEGER NOT NULL,
    data_hora_ingresso TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_participacao PRIMARY KEY (id_participacao),
    CONSTRAINT ak_participacao_usuario_grupo UNIQUE (id_usuario, id_grupo),
    CONSTRAINT fk_participacao_usuario FOREIGN KEY (id_usuario) 
        REFERENCES USUARIO (id_usuario) ON DELETE CASCADE,
    CONSTRAINT fk_participacao_grupo FOREIGN KEY (id_grupo) 
        REFERENCES GRUPO (id_grupo) ON DELETE CASCADE
);

-- Índice dedicado para resolver os gargalos do ON DELETE CASCADE e da RN06
CREATE INDEX idx_participacao_grupo ON PARTICIPACAO (id_grupo);